sql.where:
AND l.lead_type = #{leadType}
AND l.org_id = #{orgId}
AND l.dept_id = #{deptId}
${params.dataScope}

mapper.select:
SELECT COUNT(*)


    AND l.create_time >= #{from}
    AND l.create_time < (#{to}::date + interval '1 day')
    AND l.lead_type = #{leadType}
    AND l.org_id = #{orgId}
    AND l.dept_id = #{deptId}
    ${params.dataScope}

SELECT COUNT(*)


    AND lower(trim(coalesce(l.status, ''))) = 'converted'
    AND l.convert_time >= #{from}
    AND l.convert_time < (#{to}::date + interval '1 day')
    AND l.lead_type = #{leadType}
    AND l.org_id = #{orgId}
    AND l.dept_id = #{deptId}
    ${params.dataScope}

SELECT COUNT(DISTINCT l.lead_id)


    AND lower(trim(coalesce(l.status, ''))) IN ('open', 'assigned')

        AND (
            l.update_time >= #{from}
            OR EXISTS (
                SELECT 1 FROM crm_activity a
                WHERE a.relate_id = l.lead_id
                  AND a.relate_type = '业务线索'
                  AND a.started_date >= #{from}
            )
        )


        AND (
            l.update_time < (#{to}::date + interval '1 day')
            OR EXISTS (
                SELECT 1 FROM crm_activity a
                WHERE a.relate_id = l.lead_id
                  AND a.relate_type = '业务线索'
                  AND a.started_date < (#{to}::date + interval '1 day')
            )
        )

    AND l.lead_type = #{leadType}
    AND l.org_id = #{orgId}
    AND l.dept_id = #{deptId}
    ${params.dataScope}

SELECT COUNT(*)


    AND lower(trim(coalesce(l.status, ''))) = 'open'
    AND l.user_id IS NULL
    AND l.lead_type = #{leadType}
    AND l.org_id = #{orgId}
    AND l.dept_id = #{deptId}
    ${params.dataScope}

SELECT COUNT(*)


    AND lower(trim(coalesce(l.status, ''))) = 'assigned'
    AND l.lead_type = #{leadType}
    AND l.org_id = #{orgId}
    AND l.dept_id = #{deptId}
    ${params.dataScope}

SELECT COALESCE(NULLIF(TRIM(l.stage), ''), 'unknown') AS stage,
       COUNT(*) AS count


    AND lower(trim(coalesce(l.status, ''))) IN ('open', 'assigned')
    AND l.lead_type = #{leadType}
    AND l.org_id = #{orgId}
    AND l.dept_id = #{deptId}
    ${params.dataScope}

GROUP BY COALESCE(NULLIF(TRIM(l.stage), ''), 'unknown')
ORDER BY count DESC

SELECT l.owner AS owner,
       l.user_id AS userId,
       COUNT(*) AS convertedCount


    AND lower(trim(coalesce(l.status, ''))) = 'converted'
    AND l.convert_time >= #{from}
    AND l.convert_time < (#{to}::date + interval '1 day')
    AND l.lead_type = #{leadType}
    AND l.org_id = #{orgId}
    AND l.dept_id = #{deptId}
    ${params.dataScope}

GROUP BY l.owner, l.user_id
ORDER BY convertedCount DESC
LIMIT #{limit}

SELECT t.period AS period, SUM(t.new_leads) AS newLeads, SUM(t.converted_count) AS convertedCount FROM ( SELECT to_char(l.create_time, 'YYYY-MM-DD') AS period, COUNT(*)::bigint AS new_leads, 0::bigint AS converted_count
AND l.create_time >= #{from} AND l.create_time < (#{to}::date + interval '1 day') AND l.lead_type = #{leadType} ${params.dataScope}
GROUP BY to_char(l.create_time, 'YYYY-MM-DD') UNION ALL SELECT to_char(l.convert_time, 'YYYY-MM-DD') AS period, 0::bigint AS new_leads, COUNT(*)::bigint AS converted_count
AND lower(trim(coalesce(l.status, ''))) = 'converted' AND l.convert_time IS NOT NULL AND l.convert_time >= #{from} AND l.convert_time < (#{to}::date + interval '1 day') AND l.lead_type = #{leadType} ${params.dataScope}
GROUP BY to_char(l.convert_time, 'YYYY-MM-DD') ) t GROUP BY t.period ORDER BY t.period ASC
